300:   template <typename T>
301:   inline void swapArray(T* arr, size_t count) {
302:     for (size_t i = 0; i < count; ++i) {
303:         arr[i] = swap(arr[i]);
304:     }
305:   }
306: 
307:   inline void swapArray(std::byte* arr, Type type, size_t count) {
308:     if (!arr || count == 0) { return; } // No work to do
309:     dispatchType(type, [&]<Type type>() {
310:       swapArray(reinterpret_cast<TypeTraits_t<type>*>(arr), count);
311:     });
312:   }
