165:     // Copies the values from a TIFF entry to a vector of integers.
166:     template <typename T>
167:     static std::vector<int> makeIntVec(const TiffImage::IFD::Entry& entry)
168:     {
169:       std::vector<int> v(entry.count());
170:       const auto* values = reinterpret_cast<const T*>(entry.values());
171:       for (size_t i = 0; i < entry.count(); ++i) {
172:         if constexpr (is_rational_v<T>) {
173:           if (values[i].denominator == 0) {
174:             throw std::runtime_error("Rational value with zero denominator in TIFF entry");
175:           }
176:           v[i] = static_cast<int>(values[i].numerator / values[i].denominator);
177:         }
178:         else {
179:           v[i] = static_cast<int>(values[i]);
180:         }
181:       }
182:       return v;
183:     }
184: 
185:     // Copies the values from a TIFF entry to a vector of integers.
186:     // \param ifd The IFD containing the entry.
187:     // \param tag The tag to look for.
188:     // \param defaultValue An optional default value to return if the tag is
189:     //                     not found.
190:     // \return A vector of integers containing the values from the TIFF entry.
191:     static std::vector<int> getIntVec(const TiffImage::IFD& ifd, Tag tag,
192:       std::optional<std::vector<int>> defaultValue = std::nullopt)
193:     {
194:       auto it = ifd.entries().find(tag);
195:       if (it != ifd.entries().end()) {
196:         const auto& entry = it->second;
197:         return dispatchType(entry.type(), [&, entry]<Type type>() {
198:             return makeIntVec<TypeTraits_t<type>>(entry);
199:         });
200:       }
201:       if (defaultValue.has_value()) {
202:         return defaultValue.value();
203:       }
204:       throw std::runtime_error("Tag not found: " + std::to_string(static_cast<int>(tag)));
205:     }
206: 
207:     // Gets one value from a TIFF entry as an integer.
208:     // \param ifd The IFD containing the entry.
209:     // \param tag The tag to look for.
210:     // \param defaultValue An optional default value to return if the tag is
211:     //                     not found.
212:     // \return The integer value from the TIFF entry, or the default value if
213:     //         not found.
214:     static int getInt(const TiffImage::IFD& ifd, Tag tag,
215:       std::optional<int> defaultValue = std::nullopt)
216:     {
217:       std::optional<std::vector<int>> defaultValueVec;
218:       if (defaultValue.has_value()) {
219:         defaultValueVec = std::vector<int>{ defaultValue.value() };
220:       }
221:       auto v = getIntVec(ifd, tag, defaultValueVec);
222:       if (v.size() != 1) {
223:         throw std::runtime_error("Expected a single value for integer tag");
224:       }
225:       return v[0];
226:     }
227: 
228:     template <typename Comp = std::equal_to<>>
229:     static int require(
230:       const TiffImage::IFD& ifd, Tag tag, std::optional<int> defaultValue,
231:       int requiredValue, Comp&& comp = {})
232:     {
233:       const int value = getInt(ifd, tag, defaultValue);
234:       if (!comp(value, requiredValue)) {
235:         throw FormatNotSupportedError(
236:           "Unsupported " + std::to_string(static_cast<int>(tag)) +
237:           " value: " + std::to_string(value) +
238:           ", expected: " + std::to_string(requiredValue));
239:       }
240:       return value;
241:     }
