147:         }
148:         case Type::SBYTE:
149:           os << " " << static_cast<int>(*reinterpret_cast<const TypeTraits_t<Type::SBYTE>*>(value));
150:           break;
151:         case Type::UNDEFINED: {
152:           const auto* undefined = reinterpret_cast<const TypeTraits_t<Type::UNDEFINED>*>(value);
153:           os << " 0x" << std::hex << std::setw(2) << std::setfill('0')
154:              << static_cast<int>(*undefined) << std::dec << std::setw(1) <<std::setfill(' ');
155:           break;
156:         }
157:         case Type::SSHORT:
158:           os << " " << *reinterpret_cast<const TypeTraits_t<Type::SSHORT>*>(value);
159:           break;
